using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using Jindan.Contracts;
using Jindan.Core;
using static Jindan.Core.DomainRules;
namespace Jindan.Infrastructure;

public sealed partial class LocalWorkspace
{
    const long PackageLimit = 512L * 1024 * 1024; const int PackageEntries = 10000;
    sealed class ExportData { public string Format { get; set; } = "jindan-workspace-export/1"; public int SchemaVersion { get; set; } = 1; public List<WorkRecord> Records { get; set; } = []; public List<StoredAsset> Assets { get; set; } = []; }
    sealed class RollbackData { public long AppliedRevision { get; set; } public State Before { get; set; } = new(); }
    static void Destination(string path) { Require(Path.IsPathFullyQualified(path) && !path.StartsWith("\\\\", StringComparison.Ordinal) && !path.StartsWith("//", StringComparison.Ordinal) && path.IndexOf(':', 2) < 0, "DESTINATION", "Use an absolute local path for a new copy."); var absolute = Path.GetFullPath(path); var backup = Path.GetFullPath("E:/jindan").TrimEnd(Path.DirectorySeparatorChar); Require(!absolute.Equals(backup, StringComparison.OrdinalIgnoreCase) && !absolute.StartsWith(backup + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase), "PROTECTED_ROOT", "The preserved backup workspace is read-only."); var legacy = Path.GetFullPath("F:/jindan").TrimEnd(Path.DirectorySeparatorChar); Require(!absolute.Equals(legacy, StringComparison.OrdinalIgnoreCase) && !absolute.StartsWith(legacy + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase), "PROTECTED_ROOT", "The preserved legacy workspace is read-only."); var maintenance = Path.GetFullPath("F:/jindan-maintenance").TrimEnd(Path.DirectorySeparatorChar); Require(!absolute.Equals(maintenance, StringComparison.OrdinalIgnoreCase) && !absolute.StartsWith(maintenance + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase), "PROTECTED_ROOT", "Maintenance evidence is read-only."); Require(!File.Exists(absolute), "DESTINATION", "The export destination must not already exist."); CheckNoLinks(Path.GetDirectoryName(absolute)!); }
    static void StreamCopy(Stream input, Stream output, CancellationToken ct) { var buffer = new byte[128 * 1024]; int read; while ((read = input.Read(buffer)) > 0) { ct.ThrowIfCancellationRequested(); output.Write(buffer, 0, read); } ct.ThrowIfCancellationRequested(); }
    public Task<string> ExportAsync(Identity actor, string destination, CancellationToken ct = default) => Locked(() => { var user = Actor(actor); Destination(destination); var data = new ExportData { Records = _state.Records.Where(r => Readable(user, r)).Select(Copy).ToList(), Assets = _state.Assets.Where(a => user.Role == "admin" || user.ProjectIds.Contains(a.ProjectId)).Select(a => JsonSerializer.Deserialize<StoredAsset>(JsonSerializer.Serialize(a, Json), Json)!).ToList() }; Require(data.Records.Count <= 10000 && data.Assets.Select(a => a.Sha256).Distinct().Count() < PackageEntries && data.Assets.DistinctBy(a => a.Sha256).Sum(a => a.Size) <= PackageLimit - 16 * 1024 * 1024, "EXPORT_LIMIT", "Split this workspace export into a smaller selection."); var manifestBytes = JsonSerializer.SerializeToUtf8Bytes(data, Json); Require(manifestBytes.Length <= 16 * 1024 * 1024, "EXPORT_LIMIT", "Export manifest exceeds16MiB."); var temp = destination + ".tmp-" + Guid.NewGuid().ToString("N"); try { using (var output = new FileStream(temp, FileMode.CreateNew, FileAccess.ReadWrite, FileShare.None)) { using (var zip = new ZipArchive(output, ZipArchiveMode.Create, true)) { using (var json = zip.CreateEntry("data.json").Open()) json.Write(manifestBytes); foreach (var asset in data.Assets.DistinctBy(a => a.Sha256)) { ct.ThrowIfCancellationRequested(); var blob = Blob(asset.Sha256); Require(File.Exists(blob) && FileHash(blob) == asset.Sha256, "CORRUPT_ASSET", "An export asset differs from its content hash."); using var input = new FileStream(blob, FileMode.Open, FileAccess.Read, FileShare.Read); using var entry = zip.CreateEntry("assets/" + asset.Sha256 + ".blob", CompressionLevel.Fastest).Open(); StreamCopy(input, entry, ct); } } output.Flush(true); } Require(new FileInfo(temp).Length <= 256L * 1024 * 1024, "EXPORT_LIMIT", "Compressed export exceeds256MiB."); ct.ThrowIfCancellationRequested(); File.Move(temp, destination); return destination; } finally { if (File.Exists(temp)) File.Delete(temp); } }, ct);
    (ExportData Data, string Hash) ReadPackage(string path, CancellationToken ct) { Require(Path.IsPathFullyQualified(path) && File.Exists(path), "IMPORT_PATH", "Select an existing local import package."); Require(new FileInfo(path).Length <= 256L * 1024 * 1024, "IMPORT_LIMIT", "Import archive exceeds256MiB."); try { var bytes = File.ReadAllBytes(path); ct.ThrowIfCancellationRequested(); var hash = Convert.ToHexStringLower(SHA256.HashData(bytes)); using var stream = new MemoryStream(bytes, false); using var zip = new ZipArchive(stream, ZipArchiveMode.Read); Require(zip.Entries.Count is > 0 and <= PackageEntries, "IMPORT_LIMIT", "Import entry count is invalid."); var names = new HashSet<string>(StringComparer.OrdinalIgnoreCase); long expanded = 0; foreach (var entry in zip.Entries) { Require(names.Add(entry.FullName), "DUPLICATE_ZIP", "Duplicate import ZIP entries are forbidden."); Require(entry.FullName == "data.json" || entry.FullName.StartsWith("assets/", StringComparison.Ordinal) && entry.FullName.Length == 76 && entry.FullName.EndsWith(".blob", StringComparison.Ordinal) && entry.FullName[7..71].All(c => char.IsAsciiHexDigit(c)) && entry.FullName[7..71] == entry.FullName[7..71].ToLowerInvariant(), "IMPORT_PATH", "Unexpected or unsafe import entry path."); expanded = checked(expanded + entry.Length); Require(expanded <= PackageLimit, "IMPORT_LIMIT", "Expanded import exceeds512MiB."); } var manifest = zip.GetEntry("data.json"); Require(manifest is not null && manifest.Length <= 16 * 1024 * 1024, "IMPORT_LIMIT", "Import data manifest is missing or too large."); using var dataStream = manifest!.Open(); var data = JsonSerializer.Deserialize<ExportData>(dataStream, Json); Require(data is not null && data.Format == "jindan-workspace-export/1" && data.SchemaVersion == 1, "SCHEMA_FUTURE", "Unsupported import schema."); Require(data!.Records is not null && data.Assets is not null && data.Records.Count <= 10000 && data.Assets.Count <= 10000, "IMPORT_LIMIT", "Invalid import collections."); Require(data.Records.All(r => r is not null && r.Fields is not null) && data.Assets.All(a => a is not null && a.Sha256 is not null && a.OriginalName is not null && a.MediaType is not null), "IMPORT_DATA", "Import entries are incomplete."); Require(data.Records.Select(r => r.Id).Distinct().Count() == data.Records.Count && data.Assets.Select(a => a.Id).Distinct().Count() == data.Assets.Count, "IMPORT_DUPLICATE", "Duplicate imported identities."); foreach (var r in data.Records) { Require(!string.IsNullOrWhiteSpace(r.Id) && r.Revision > 0, "IMPORT_DATA", "Invalid record identity or revision."); var schema = Schema(r.Kind); ValidateFields(schema, r.Fields); Require(schema.ProjectScoped ? r.ProjectId is not null && data.Records.Any(p => IsProject(p.Kind) && p.Id == r.ProjectId) : r.ProjectId is null, "PROJECT_SCOPE", "An imported child has no matching imported project."); } foreach (var asset in data.Assets) { Require(data.Records.Any(p => IsProject(p.Kind) && p.Id == asset.ProjectId), "PROJECT_SCOPE", "An imported asset has no matching project."); var entry = zip.GetEntry("assets/" + asset.Sha256 + ".blob"); Require(entry is not null && entry.Length == asset.Size && asset.Size <= 256L * 1024 * 1024, "IMPORT_ASSET", "Missing or oversized import asset."); using var contents = entry!.Open(); Require(Convert.ToHexStringLower(SHA256.HashData(contents)) == asset.Sha256, "IMPORT_ASSET", "Import asset content hash differs."); } ValidateImportLinks(data); Require(zip.Entries.Count == 1 + data.Assets.Select(a => a.Sha256).Distinct().Count(), "IMPORT_ASSET", "Unreferenced import assets are forbidden."); return (data, hash); } catch (WorkspaceException) { throw; } catch (Exception e) when (e is JsonException or InvalidDataException or OverflowException) { throw new WorkspaceException("CORRUPT_IMPORT", "The import package is malformed."); } }
    public Task<ImportPreview> PreviewImportAsync(Identity actor, string path, CancellationToken ct = default) => Locked(() => { Admin(Actor(actor)); var (data, hash) = ReadPackage(path, ct); return new ImportPreview(Path.GetFullPath(path), hash, data.Records.Count, data.SchemaVersion, ["Import creates new record/project IDs; identities and permissions are not imported.", "Existing records remain unchanged. Rollback is available until the next data mutation."]); }, ct);
    public async Task ImportAsync(Identity actor, ImportPreview preview, bool confirmed, CancellationToken ct = default)
    {
        await Locked(() =>
        {
            var user = Actor(actor); Admin(user); Require(confirmed, "CONFIRMATION", "Confirm the reviewed import into new copies."); ValidateOriginalImport(preview); var (data, hash) = ReadPackage(preview.SourcePath, ct); Require(hash == preview.Sha256 && data.SchemaVersion == preview.SchemaVersion && data.Records.Count == preview.Records, "STALE_PREVIEW", "The import package differs from the preview."); var next = Clone(); var ids = data.Records.ToDictionary(r => r.Id, _ => Guid.NewGuid().ToString("N")); var assetIds = data.Assets.ToDictionary(a => a.Id, _ => Guid.NewGuid().ToString("N")); foreach (var r in data.Records) { var fields = new Dictionary<string, string>(r.Fields, StringComparer.Ordinal); if (fields.ContainsKey("attachmentIds")) fields["attachmentIds"] = string.Join(",", AttachmentIds(fields).Select(id => assetIds[id])); foreach (var key in fields.Keys.ToArray()) { if ((key.EndsWith("AssetId", StringComparison.Ordinal) || key == "assetId" || key == "attachmentId") && assetIds.TryGetValue(fields[key], out var assetId)) fields[key] = assetId; else if ((key.EndsWith("ProjectId", StringComparison.Ordinal) || key is "folderId" or "parentId" or "relatedTask") && ids.TryGetValue(fields[key], out var projectId)) fields[key] = projectId; } next.Records.Add(r with { Id = ids[r.Id], ProjectId = r.ProjectId is null ? null : ids[r.ProjectId], OwnerId = user.Id, Revision = 1, Fields = fields }); }
            using (var source = ZipFile.OpenRead(preview.SourcePath)) { foreach (var a in data.Assets) { ct.ThrowIfCancellationRequested(); var blob = Blob(a.Sha256); if (File.Exists(blob)) Require(FileHash(blob) == a.Sha256, "CORRUPT_ASSET", "Existing local asset differs from the import hash."); else { var temp = blob + ".tmp-" + Guid.NewGuid().ToString("N"); try { using (var input = source.GetEntry("assets/" + a.Sha256 + ".blob")!.Open()) using (var output = new FileStream(temp, FileMode.CreateNew, FileAccess.Write, FileShare.None)) { StreamCopy(input, output, ct); output.Flush(true); } Require(FileHash(temp) == a.Sha256, "STALE_PREVIEW", "Import bytes changed during extraction."); File.Move(temp, blob); } finally { if (File.Exists(temp)) File.Delete(temp); } } next.Assets.Add(new() { Id = assetIds[a.Id], ProjectId = ids[a.ProjectId], OwnerId = user.Id, Sha256 = a.Sha256, OriginalName = Path.GetFileName(a.OriginalName), Size = a.Size, MediaType = a.MediaType }); } }
            Require(FileHash(preview.SourcePath) == preview.Sha256, "STALE_PREVIEW", "Import package changed during application."); ValidateOriginalImport(preview); AtomicBytes(Path.Combine(_root, "import-rollback.json"), JsonSerializer.SerializeToUtf8Bytes(new RollbackData { AppliedRevision = next.Revision + 1, Before = Clone() }, Json), null); Commit(next, ct); return true;
        }, ct);
    }
    public async Task RollbackLastImportAsync(Identity actor, bool confirmed, CancellationToken ct = default) { await Locked(() => { Admin(Actor(actor)); Require(confirmed, "CONFIRMATION", "Confirm import rollback."); var path = Path.Combine(_root, "import-rollback.json"); Require(File.Exists(path), "NO_ROLLBACK", "No import rollback snapshot is available."); var rollback = JsonSerializer.Deserialize<RollbackData>(File.ReadAllBytes(path), Json); Require(rollback is not null && rollback.AppliedRevision == _state.Revision, "REVISION", "The workspace changed after import; automatic rollback would overwrite newer work."); Require(rollback!.Before.SchemaVersion == 1, "SCHEMA_FUTURE", "The rollback schema is unsupported."); var before = rollback.Before; before.Revision = _state.Revision; Commit(before, ct); File.Move(path, path + ".used-" + Guid.NewGuid().ToString("N")); return true; }, ct); }
}
